static const lv_image_dsc_t *const table[QZ_FACE_STATE_COUNT][QZ_OTTO_SIZE_COUNT] = {
    [QZ_FACE_IDLE] = { &dsc_neutral_60, &dsc_neutral_88, &dsc_neutral_164 },
    [QZ_FACE_SPEAKING] = { &dsc_happy_60, &dsc_happy_88, &dsc_happy_164 },
    [QZ_FACE_THINKING] = { &dsc_thinking_60, &dsc_thinking_88, &dsc_thinking_164 },
    [QZ_FACE_HAPPY] = { &dsc_laughing_60, &dsc_laughing_88, &dsc_laughing_164 },
    [QZ_FACE_CONFUSED] = { &dsc_confused_60, &dsc_confused_88, &dsc_confused_164 },
    [QZ_FACE_LOVE] = { &dsc_loving_60, &dsc_loving_88, &dsc_loving_164 },
    [QZ_FACE_SURPRISED] = { &dsc_surprised_60, &dsc_surprised_88, &dsc_surprised_164 },
    [QZ_FACE_SLEEPY] = { &dsc_sleepy_60, &dsc_sleepy_88, &dsc_sleepy_164 },
    [QZ_FACE_WINK] = { &dsc_winking_60, &dsc_winking_88, &dsc_winking_164 },
    [QZ_FACE_EXCITED] = { &dsc_silly_60, &dsc_silly_88, &dsc_silly_164 },
};

int32_t qz_otto_px(qz_otto_size_t size)
{
    switch (size) {
        case QZ_OTTO_60: return 60;
        case QZ_OTTO_88: return 88;
        case QZ_OTTO_164: return 164;
        default: return 88;
    }
}

const char *qz_otto_emoji_name(qz_face_state_t state)
{
    switch (state) {
        case QZ_FACE_IDLE: return "neutral";
        case QZ_FACE_SPEAKING: return "happy";
        case QZ_FACE_THINKING: return "thinking";
        case QZ_FACE_HAPPY: return "laughing";
        case QZ_FACE_CONFUSED: return "confused";
        case QZ_FACE_LOVE: return "loving";
        case QZ_FACE_SURPRISED: return "surprised";
        case QZ_FACE_SLEEPY: return "sleepy";
        case QZ_FACE_WINK: return "winking";
        case QZ_FACE_EXCITED: return "silly";
        default: return "neutral";
    }
}

const lv_image_dsc_t *qz_otto_emoji(qz_face_state_t state, qz_otto_size_t size)
{
    if (state >= QZ_FACE_STATE_COUNT) state = QZ_FACE_IDLE;
    if (size >= QZ_OTTO_SIZE_COUNT) size = QZ_OTTO_88;
    return table[state][size];
}
